CREATE DATABASE IF NOT EXISTS customer_behavior;

use customer_behavior;

select * from customer
limit 10;

-- what is the total revenue generated by male vs female employees

select gender, sum(purchase_amount) as revenue
from customer
group by gender;

--  which cusotmer uses a discount but still spent more than the avg of purchase amount
select customer_id,purchase_amount
from customer
where discount_applied='yes' and purchase_amount>=
(
select avg(purchase_amount) 
from customer
);


-- which are the top 5 products with the highest avg review rating

select item_purchased, round(avg(review_rating),2) as 'Average Product Rating'
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- commpare the average purchase amount for the standard and express shipping

select shipping_type, round(avg(purchase_amount) ,2) 
from customer
where shipping_type in ('Standard','Express')
group by shipping_type;

-- do subscribe customers spent more comaore the avg spend and total
-- revenue betwwn the subscribers and non-subscribers

select subscription_status,
count(customer_id) as total_customers,
round(avg(purchase_amount),2) as avg_spend,
round(sum(purchase_amount),2) as total_revenue
from customer
group by subscription_status
order by total_revenue, avg_spend desc;


-- which 5 products have the highest percentage of purchases with discount

select item_purchased,
round(100 * sum(case when discount_applied = 'Yes' then 1 else 0 end) / count(*),2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;

-- segments customers into new, returning and loyal based on their total nr of previuous
-- purchases. and show the count of each segment

with customer_type as
(
select customer_id, previous_purchases,
case
 when previous_purchases=1 then 'New'
 when previous_purchases between 2 and 10 then 'Returning'
 else 'Loyal'
 end as customer_segment
from customer
) 

select customer_segment, count(*) as 'Number of Customers'
from customer_type
group by customer_segment;


-- what are the top 3 most purchased product within each category

with item_count as 
(
select category, item_purchased,
count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from customer
group by category, item_purchased
)

select item_rank,category,item_purchased, total_orders
from item_count
where item_rank<=3;


-- ARE 	CUSTOMERS WHO ARE REPEAT BUYERS (MORE THAN 5 PREVIOUS PURCAHSES) ALSO LIKELY TO SUBSCRIBE

select subscription_status,
count(customer_id) as repeat_buyers
from customer
where previous_purchases>5
group by subscription_status;

-- check revenue by age group

select age_group,
sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;


 








     